def modulate(x, shift, scale):
    return x * (1 + scale) + shift


class FlowTimestepEmbedder(nn.Module):
    def __init__(self, hidden_size, frequency_embedding_size=256):
        super().__init__()
        self.frequency_embedding_size = frequency_embedding_size
        self.mlp = nn.Sequential(
            nn.Linear(frequency_embedding_size, hidden_size, bias=True),
            nn.SiLU(),
            nn.Linear(hidden_size, hidden_size, bias=True),
        )

    @staticmethod
    def timestep_embedding(t, dim, max_period=10000):
        half = dim // 2
        freqs = torch.exp(
            -torch.log(torch.tensor(max_period, device=t.device, dtype=torch.float32))
            * torch.arange(0, half, dtype=torch.float32, device=t.device)
            / half
        )
        args = t[:, None].float() * freqs[None]
        embedding = torch.cat([torch.cos(args), torch.sin(args)], dim=-1)
        if dim % 2:
            embedding = torch.cat([embedding, torch.zeros_like(embedding[:, :1])], dim=-1)
        return embedding

    def forward(self, t):
        emb = self.timestep_embedding(t, self.frequency_embedding_size)
        return self.mlp(emb.to(dtype=self.mlp[0].weight.dtype))


class FlowResBlock(nn.Module):
    def __init__(self, channels):
        super().__init__()
        self.in_ln = nn.LayerNorm(channels, eps=1e-6)
        self.mlp = nn.Sequential(
            nn.Linear(channels, channels, bias=True),
            nn.SiLU(),
            nn.Linear(channels, channels, bias=True),
        )
        self.adaLN_modulation = nn.Sequential(
            nn.SiLU(),
            nn.Linear(channels, 3 * channels, bias=True),
        )

    def forward(self, x, y):
        shift_mlp, scale_mlp, gate_mlp = self.adaLN_modulation(y).chunk(3, dim=-1)
        h = modulate(self.in_ln(x), shift_mlp, scale_mlp)
        h = self.mlp(h)
        return x + gate_mlp * h


class FlowFinalLayer(nn.Module):
    def __init__(self, model_channels, out_channels):
        super().__init__()
        self.norm_final = nn.LayerNorm(model_channels, elementwise_affine=False, eps=1e-6)
        self.linear = nn.Linear(model_channels, out_channels, bias=True)
        self.adaLN_modulation = nn.Sequential(
            nn.SiLU(),
            nn.Linear(model_channels, 2 * model_channels, bias=True),
        )

    def forward(self, x, c):
        shift, scale = self.adaLN_modulation(c).chunk(2, dim=-1)
        x = modulate(self.norm_final(x), shift, scale)
        return self.linear(x)


class FlowMatchingHead(nn.Module):
    def __init__(
        self,
        target_channels,
        z_channels,
        width=1024,
        depth=3,
        time_scale=1000.0,
        sample_method="heun",
    ):
        super().__init__()
        self.target_channels = target_channels
        self.time_scale = float(time_scale)
        self.sample_method = sample_method
        self.time_embed = FlowTimestepEmbedder(width)
        self.cond_embed = nn.Linear(z_channels, width)
        self.input_proj = nn.Linear(target_channels, width)
        self.res_blocks = nn.ModuleList([FlowResBlock(width) for _ in range(depth)])
        self.final_layer = FlowFinalLayer(width, target_channels)
        self.last_forward_stats = {}
        self.initialize_weights()

    @staticmethod
    def _rms_stat(x):
        return x.detach().float().pow(2).mean().sqrt()

    def initialize_weights(self):
        def _basic_init(module):
            if isinstance(module, nn.Linear):
                torch.nn.init.xavier_uniform_(module.weight)
                if module.bias is not None:
                    nn.init.constant_(module.bias, 0)
        self.apply(_basic_init)
        nn.init.normal_(self.time_embed.mlp[0].weight, std=0.02)
        nn.init.normal_(self.time_embed.mlp[2].weight, std=0.02)
        for block in self.res_blocks:
            nn.init.constant_(block.adaLN_modulation[-1].weight, 0)
            nn.init.constant_(block.adaLN_modulation[-1].bias, 0)
        nn.init.constant_(self.final_layer.adaLN_modulation[-1].weight, 0)
        nn.init.constant_(self.final_layer.adaLN_modulation[-1].bias, 0)
        nn.init.constant_(self.final_layer.linear.weight, 0)
        nn.init.constant_(self.final_layer.linear.bias, 0)

    def forward(self, target, z, mask=None):
        target = target.float()
        noise = torch.randn_like(target)
        t = torch.rand(target.shape[0], device=target.device, dtype=target.dtype)
        x_t = (1.0 - t[:, None]) * noise + t[:, None] * target
        velocity = target - noise

        pred = self.predict_velocity(x_t, t, z)
        loss = (pred - velocity).pow(2).mean(dim=-1)
        self.last_forward_stats.update(
            {
                "flow/target_rms": self._rms_stat(target),
                "flow/noise_rms": self._rms_stat(noise),
                "flow/velocity_target_rms": self._rms_stat(velocity),
                "flow/mse": loss.detach().float().mean(),
            }
        )
        if mask is not None:
            mask = mask.to(loss.dtype)
            return (loss * mask).sum() / mask.sum().clamp_min(1.0)
        return loss.mean()

    def predict_velocity(self, x_t, t, z):
        model_dtype = self.input_proj.weight.dtype
        z = z.to(dtype=self.cond_embed.weight.dtype)
        x = self.input_proj(x_t.to(dtype=model_dtype))
        scaled_t = t.float() * self.time_scale
        cond = self.cond_embed(z).to(dtype=model_dtype)
        y = self.time_embed(scaled_t).to(dtype=model_dtype) + cond
        for block in self.res_blocks:
            x = block(x, y)
        pred = self.final_layer(x, y).float()
        self.last_forward_stats = {
            "flow/input_xt_rms": self._rms_stat(x_t),
            "flow/hidden_z_rms": self._rms_stat(z),
            "flow/cond_rms": self._rms_stat(cond),
            "flow/time_rms": self._rms_stat(y - cond),
            "flow/y_rms": self._rms_stat(y),
            "flow/pred_velocity_rms": self._rms_stat(pred),
        }
        return pred

    def sample(self, z, num_steps=50, temperature=1.0, sample_method=None, x_init=None):
        sample_method = (sample_method or self.sample_method or "euler").lower()
        if x_init is None:
            x = torch.randn(z.shape[0], self.target_channels, device=z.device, dtype=z.dtype) * temperature
        else:
            x = x_init.to(device=z.device, dtype=z.dtype).clone()
        dt = 1.0 / float(num_steps)
        for step in range(num_steps):
            t = torch.full((z.shape[0],), step / float(num_steps), device=z.device, dtype=torch.float32)
            v = self.predict_velocity(x, t, z).to(dtype=x.dtype)
            if sample_method == "heun":
                x_euler = x + dt * v
                next_t = torch.full(
                    (z.shape[0],),
                    (step + 1) / float(num_steps),
                    device=z.device,
                    dtype=torch.float32,
                )
                next_v = self.predict_velocity(x_euler, next_t, z).to(dtype=x.dtype)
                x = x + 0.5 * dt * (v + next_v)
            elif sample_method == "euler":
                x = x + dt * v
            else:
                raise ValueError(f"Unsupported flow sample_method: {sample_method}")
        return x
    

class ImageLatentProjector(nn.Module):
    def __init__(self, latent_dim, hidden_size, projector_width=None):
        super().__init__()
        projector_width = int(projector_width or hidden_size * 2)
        self.in_norm = nn.LayerNorm(latent_dim, eps=1e-6)
        self.fc1 = nn.Linear(latent_dim, projector_width, bias=True)
        self.act = nn.GELU()
        self.fc2 = nn.Linear(projector_width, hidden_size, bias=True)
        self.out_norm = nn.LayerNorm(hidden_size, eps=1e-6)

    @property
    def weight_dtype(self):
        return self.fc1.weight.dtype

    def forward(self, latents):
        x = latents.to(dtype=self.in_norm.weight.dtype)
        x = self.in_norm(x).to(dtype=self.fc1.weight.dtype)
        x = self.fc1(x)
        x = self.act(x)
        x = self.fc2(x)
        return self.out_norm(x)


def _compute_default_rope_parameters(config: Qwen3Config, device=None):
    base = getattr(config, "rope_theta", 10000.0)
    head_dim = getattr(config, "head_dim", config.hidden_size // config.num_attention_heads)
    partial_rotary_factor = getattr(config, "partial_rotary_factor", 1.0)
    dim = int(head_dim * partial_rotary_factor)
    inv_freq = 1.0 / (
        base ** (torch.arange(0, dim, 2, dtype=torch.float32, device=device) / dim)
    )
    return inv_freq, 1.0


@use_kernel_forward_from_hub("RMSNorm")
class Qwen3RMSNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        """
        Qwen3RMSNorm is equivalent to T5LayerNorm
        """
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        return flash_rms_norm(
            hidden_states, weight=self.weight, bias=None, eps=self.variance_epsilon)
        '''
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * \
            torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)
        '''

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.variance_epsilon}"


class Qwen3MLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size
        self.gate_proj = nn.Linear(
            self.hidden_size, self.intermediate_size, bias=False)
        self.up_proj = nn.Linear(
            self.hidden_size, self.intermediate_size, bias=False)
        self.down_proj = nn.Linear(
            self.intermediate_size, self.hidden_size, bias=False)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, x):
        if liger_kernel_is_available:
            return self.down_proj(LigerSiLUMulFunction.apply(self.gate_proj(x), self.up_proj(x)))
        else:
            down_proj = self.down_proj(self.act_fn(self.gate_proj(x)) * self.up_proj(x))
            return down_proj


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rotary_pos_emb(X0_q, XT_q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
    """Applies Rotary Position Embedding to the query and key tensors.

    Args:
        q (`torch.Tensor`): The query tensor.
        k (`torch.Tensor`): The key tensor.
        cos (`torch.Tensor`): The cosine part of the rotary embedding.
        sin (`torch.Tensor`): The sine part of the rotary embedding.
        position_ids (`torch.Tensor`, *optional*):
            Deprecated and unused.
        unsqueeze_dim (`int`, *optional*, defaults to 1):
            The 'unsqueeze_dim' argument specifies the dimension along which to unsqueeze cos[position_ids] and
            sin[position_ids] so that they can be properly broadcasted to the dimensions of q and k. For example, note
            that cos[position_ids] and sin[position_ids] have the shape [batch_size, seq_len, head_dim]. Then, if q and
            k have the shape [batch_size, heads, seq_len, head_dim], then setting unsqueeze_dim=1 makes
            cos[position_ids] and sin[position_ids] broadcastable to the shapes of q and k. Similarly, if q and k have
            the shape [batch_size, seq_len, heads, head_dim], then set unsqueeze_dim=2.
    Returns:
        `tuple(torch.Tensor)` comprising of the query and key tensors rotated using the Rotary Position Embedding.
    """
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    X0_q_embed = (X0_q * cos) + (rotate_half(X0_q) * sin)
    XT_q_embed = (XT_q * cos) + (rotate_half(XT_q) * sin) if XT_q is not None else None
    k_embed = (k * cos) + (rotate_half(k) * sin)
    
    return X0_q_embed, XT_q_embed, k_embed


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(batch, num_key_value_heads, n_rep, slen, head_dim)
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


@torch.compile(fullgraph=True, mode="max-autotune-no-cudagraphs")
def compiled_flex_attention(query, key, value, attention_mask, scaling, enable_gqa):
    """编译优化的 flex_attention 包装函数"""
    return flex_attention(
        query=query,
        key=key,
        value=value,
        score_mod=None,
        block_mask=attention_mask,
        scale=scaling,
        enable_gqa=enable_gqa,
        return_lse=False,
    )

@torch.compile(
    fullgraph=True,
    mode="default",
    dynamic=True
)
def dynamic_flex_attention(query, key, value, attention_mask, scaling, enable_gqa):
    """自适应tokens长度的 flex_attention 包装函数"""
    return flex_attention(
        query=query,
        key=key,
        value=value,
        score_mod=None,
        block_mask=attention_mask,
        scale=scaling,
        enable_gqa=enable_gqa,
        return_lse=False,
    )

    
class Qwen3Attention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(self, config: Qwen3Config, layer_idx: int):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.head_dim = getattr(config, "head_dim", config.hidden_size // config.num_attention_heads)
        self.num_key_value_groups = config.num_attention_heads // config.num_key_value_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = config.attention_dropout

        self.q_proj = nn.Linear(
            config.hidden_size, config.num_attention_heads * self.head_dim, bias=config.attention_bias
        )
        self.k_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.v_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.o_proj = nn.Linear(
            config.num_attention_heads * self.head_dim, config.hidden_size, bias=config.attention_bias
        )
        self.q_norm = Qwen3RMSNorm(self.head_dim, eps=config.rms_norm_eps)  # unlike olmo, only on the head dim!
        self.k_norm = Qwen3RMSNorm(self.head_dim, eps=config.rms_norm_eps)  # thus post q_norm does not need reshape

    @deprecate_kwarg("past_key_value", new_name="past_key_values", version="4.58")
    def forward(
        self,
        X0_hidden_states: torch.Tensor,
        XT_hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: BlockMask,
        past_key_values: Optional[Cache] = None,
        cache_position: Optional[torch.LongTensor] = None,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
        input_shape = X0_hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)
            
        XT_query_states = self.q_norm(self.q_proj(XT_hidden_states).view(hidden_shape)).transpose(1, 2) if XT_hidden_states is not None else None
        
        X0_query_states = self.q_norm(self.q_proj(X0_hidden_states).view(hidden_shape)).transpose(1, 2)
        X0_key_states = self.k_norm(self.k_proj(X0_hidden_states).view(hidden_shape)).transpose(1, 2)
        X0_value_states = self.v_proj(X0_hidden_states).view(hidden_shape).transpose(1, 2)

        cos, sin = position_embeddings
        X0_query_states, XT_query_states, X0_key_states,  = apply_rotary_pos_emb(X0_query_states, XT_query_states, X0_key_states, cos, sin)

        if past_key_values is not None:
            # sin and cos are specific to RoPE models; cache_position needed for the static cache
            cache_kwargs = {"sin": sin, "cos": cos, "cache_position": cache_position}
            X0_key_states, X0_value_states = past_key_values.update(X0_key_states, X0_value_states, self.layer_idx, cache_kwargs)
        
        # 检查是否需要 GQA (Grouped Query Attention)
        enable_gqa = self.config.num_attention_heads != self.config.num_key_value_heads
        
        if self.training == False:
            X0_attn_output = dynamic_flex_attention(
                query=X0_query_states,
                key=X0_key_states,
                value=X0_value_states,
                attention_mask=attention_mask,  # 直接传入 BlockMask
                scaling=self.scaling,  # 使用预定义的缩放因子
                enable_gqa=enable_gqa,  # 如果 kv heads 少于 q heads，需要启用
            )
            XT_attn_output = dynamic_flex_attention(
                query=XT_query_states,
                key=X0_key_states,
                value=X0_value_states,
                attention_mask=attention_mask,  # 直接传入 BlockMask
                scaling=self.scaling,  # 使用预定义的缩放因子
                enable_gqa=enable_gqa,  # 如果 kv heads 少于 q heads，需要启用
            ) if XT_query_states is not None else None
            attn_weights = None
        else:
            # 调用 flex_attention
            X0_attn_output = compiled_flex_attention(
                query=X0_query_states,
                key=X0_key_states,
                value=X0_value_states,
                attention_mask=attention_mask,  # 直接传入 BlockMask
                scaling=self.scaling,  # 使用预定义的缩放因子
                enable_gqa=enable_gqa,  # 如果 kv heads 少于 q heads，需要启用
            )
            XT_attn_output = compiled_flex_attention(
                query=XT_query_states,
                key=X0_key_states,
                value=X0_value_states,
                attention_mask=attention_mask,  # 直接传入 BlockMask
                scaling=self.scaling,  # 使用预定义的缩放因子
                enable_gqa=enable_gqa,  # 如果 kv heads 少于 q heads，需要启用
            ) if XT_query_states is not None else None
            attn_weights = None
        
        # attn_output 形状: (batch, heads, seq_len, head_dim)
        # 需要转换回 (batch, seq_len, hidden_size)
        X0_attn_output = X0_attn_output.transpose(1, 2).reshape(*input_shape, -1).contiguous()
        XT_attn_output = XT_attn_output.transpose(1, 2).reshape(*input_shape, -1).contiguous() if XT_attn_output is not None else None
        X0_attn_output = self.o_proj(X0_attn_output)
        XT_attn_output = self.o_proj(XT_attn_output) if XT_attn_output is not None else None
        
        return X0_attn_output, XT_attn_output, attn_weights


class Qwen3DecoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: Qwen3Config, layer_idx: int):
        super().__init__()
        self.hidden_size = config.hidden_size

        self.self_attn = Qwen3Attention(config=config, layer_idx=layer_idx)

        self.mlp = Qwen3MLP(config)
        self.input_layernorm = Qwen3RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.post_attention_layernorm = Qwen3RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.attention_type = config.layer_types[layer_idx]

    @deprecate_kwarg("past_key_value", new_name="past_key_values", version="4.58")
    def forward(
        self,
        X0_hidden_states: torch.Tensor,
        XT_hidden_states: torch.Tensor,
        attention_mask: BlockMask,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[Cache] = None,
        use_cache: Optional[bool] = False,
        cache_position: Optional[torch.LongTensor] = None,
        position_embeddings: Optional[tuple[torch.Tensor, torch.Tensor]] = None,  # necessary, but kept here for BC
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        X0_residual = X0_hidden_states
        XT_residual = XT_hidden_states if XT_hidden_states is not None else None
        X0_hidden_states = self.input_layernorm(X0_hidden_states)
        XT_hidden_states = self.input_layernorm(XT_hidden_states) if XT_hidden_states is not None else None
        # Self Attention
        X0_hidden_states, XT_hidden_states, _ = self.self_attn(
            X0_hidden_states=X0_hidden_states,
            XT_hidden_states=XT_hidden_states,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=past_key_values,
            use_cache=use_cache,
            cache_position=cache_position,
            position_embeddings=position_embeddings,
            **kwargs,
        )
        X0_hidden_states = X0_residual + X0_hidden_states
        XT_hidden_states = XT_residual + XT_hidden_states if XT_hidden_states is not None else None

        # Fully Connected
        X0_residual = X0_hidden_states
        XT_residual = XT_hidden_states if XT_hidden_states is not None else None
        X0_hidden_states = self.post_attention_layernorm(X0_hidden_states)
        XT_hidden_states = self.post_attention_layernorm(XT_hidden_states) if XT_hidden_states is not None else None
        X0_hidden_states = self.mlp(X0_hidden_states)
        XT_hidden_states = self.mlp(XT_hidden_states) if XT_hidden_states is not None else None
        X0_hidden_states = X0_residual + X0_hidden_states
        XT_hidden_states = XT_residual + XT_hidden_states if XT_hidden_states is not None else None
        return X0_hidden_states, XT_hidden_states


